head.script:
scwin.onpageload = function() {
    var jsonData = [{
        "col1": "a1",
        "col2": "a1"
    }, {
        "col1": "a2",
        "col2": "a2"
    }, {
        "col1": "a3",
        "col2": "a3"
    }, {
        "col1": "a4",
        "col2": "a4"
    }, {
        "col1": "a5",
        "col2": "a5"
    }, {
        "col1": "a6",
        "col2": "a6"
    }];
    dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    // Step 1. 샘플실행 후 브라우저의 넓이를 줄인다.
    // Step 1. Reduce the width of the browser after running the sample.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('body').css('width', '400px')");
    //Step 2. autoComplete의 List의 넓이를 확인한다.
    // Step 2. Check the width of the List of autoComplete.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#autoComplete1_button').click()");
    //Verify 2. autoComplete의 List의 넓이가 줄어든 만큼 List size도 동일하게 줄어들어 보여진다. (이전에는 List size가 기존 넓이만큼 보여짐)
    //Verify 2. As the width of the List of autoComplete is reduced, the List size is reduced to the same size.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#autoComplete1').css('width')", "120px");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#autoComplete1_gridViewItemTable').css('width') == '122px'", "true");
	WebSquare.wUnit.addCommand("assert", "Math.abs(parseInt(WebSquare.wUnit.getJq('#autoComplete1_gridViewItemTable').css('width'), 10) - 122) <= 1", "true");
    //Step 3. selectbox의 List의 넓이를 확인한다.
    // Step 3. Check the width of the List in the selectbox.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getJq('#sel1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#sel1').css('width')", "120px");
    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#sel1_gridViewItemTable').css('width') == '122px'", "true");
	WebSquare.wUnit.addCommand("assert", "Math.abs(parseInt(WebSquare.wUnit.getJq('#sel1_gridViewItemTable').css('width'), 10) - 122) <= 1", "true");	
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
